# Curated date-order sequence, honest default verification state.
records=[]
for cid, items in D.items():
    for idx, item in enumerate(items):
        name, path, desc, subcat, pricing, tags, featured = item
        name = name.strip()
        # A number of entries intentionally point to an official product subpath; domains are canonical hosts.
        parsed = urlparse('https://' + path)
        domain = parsed.netloc.lower()
        url = 'https://' + path.rstrip('/') + '/'
        safe_id = re.sub(r'[^a-z0-9]+','-',name.lower()).strip('-')
        tag_list = [t.strip() for t in tags.split(',') if t.strip()]
        records.append({
            'id': safe_id, 'name': name, 'url': url, 'domain': domain,
            'description': desc, 'category': cid,
            'subcategory': subcat, 'tags': tag_list,
            'pricing': pricing, 'platform': 'web', 'featured': bool(featured),
            'status': 'unchecked', 'addedOrder': len(records)+1
        })

# Validate constraints and report duplicates rather than silently accepting them.
assert len(records) == 300, f"expected 300, got {len(records)}; counts={ {k:len(v) for k,v in D.items()} }"
ids=[r['id'] for r in records]
domains=[r['domain'] for r in records]
assert len(set(ids)) == len(ids), [x for x in set(ids) if ids.count(x)>1]
assert len(set(domains)) == len(domains), [x for x in set(domains) if domains.count(x)>1]
assert all(r['url'].startswith('https://') and r['domain'] for r in records)
assert sum(1 for r in records if r['featured']) >= 40
assert set(r['category'] for r in records) == {c['id'] for c in cats}

base='/mnt/data/WEBSTORE'
os.makedirs(base+'/source/src/data',exist_ok=True)
with open(base+'/source/src/data/websites.json','w') as f: json.dump(records,f,ensure_ascii=False,indent=2)
with open(base+'/source/src/data/categories.ts','w') as f:
    f.write('export const categories = '+json.dumps(cats,ensure_ascii=False,indent=2)+' as const;\n')
with open(base+'/portable-data.js','w') as f:
    f.write('window.WEBSTORE_DATA = '+json.dumps(records,ensure_ascii=False,separators=(',',':'))+';\n')
print('Counts:', {k:len(v) for k,v in D.items()})
print('Total:',len(records),'unique IDs:',len(set(ids)),'unique domains:',len(set(domains)))
print('Featured:',sum(r['featured'] for r in records))
